// 7. Deviation bars
function renderDevBars(containerId, deviations, globalMedian) {
  const container = document.getElementById(containerId);
  const sorted = Object.entries(deviations).sort((a, b) => a[1].deviation_pct - b[1].deviation_pct);
  const maxAbs = Math.max(...sorted.map(([_, d]) => Math.abs(d.deviation_pct)), 30);

  sorted.forEach(([country, d]) => {
    const pct = d.deviation_pct;
    const barWidth = (Math.abs(pct) / maxAbs) * 45;
    const isPositive = pct >= 0;
    const leftPos = isPositive ? 50 : (50 - barWidth);

    container.innerHTML += `
      <div class="dev-bar-container">
        <div class="dev-bar-label">${country} <span style="font-size:0.75rem;color:#94a3b8;">(n=${d.count})</span></div>
        <div class="dev-bar-track">
          <div class="dev-bar-center"></div>
          <div class="dev-bar-fill ${isPositive ? 'positive' : 'negative'}" style="left:${leftPos}%;width:${barWidth}%;"></div>
        </div>
        <div class="dev-bar-value" style="color:${isPositive ? '#dc2626' : '#16a34a'};">${pct >= 0 ? '+' : ''}${pct.toFixed(1)}%</div>
      </div>
    `;
  });
}

